// Surface delivery failures in the execution log. A row that fails five times
// stops being claimed and would otherwise sit in the outbox unnoticed — an owner
// who never got told about a lead has no way to know a notification existed.
const { claimed = 0, sent = 0, failed = 0, suppressed = 0 } = $input.first().json;

console.warn(JSON.stringify({
  level: 'warn',
  message: 'Notification delivery failures in this batch',
  claimed, sent, failed, suppressed,
  execution_id: $execution.id,
}));

return [{ json: { claimed, sent, failed, suppressed, needs_attention: failed > 0 } }];
